// Local stand-in for ApiArk's Rust (Tauri) backend, for running the desktop
// front end in a plain browser. Installed at the Tauri IPC boundary via the
// official @tauri-apps/api/mocks helpers, so the app's own code paths
// (lib/tauri-api.ts, plugin wrappers, event listeners) run unchanged.
// All data comes from seed-data.json (generated by ../seed/generate.mjs).
import { mockIPC, mockWindows } from "@tauri-apps/api/mocks";
import { emit } from "@tauri-apps/api/event";
import seedRaw from "./seed-data.json";

/* eslint-disable @typescript-eslint/no-explicit-any */
type Any = any;
const seed: Any = structuredClone(seedRaw);
const HOME: string = seed.home;
const collections: Any[] = seed.collections;
const files: Record<string, Any> = {};
const responses: Record<string, Any> = {};
for (const c of collections) {
  Object.assign(files, c.files);
  Object.assign(responses, c.responses);
}
let settings = seed.settings;
let persisted = seed.persistedState;
let history: Any[] = seed.history;
let monitors: Any[] = seed.monitors;
const monitorResults: Record<string, Any[]> = seed.monitorResults;
let audit: Any[] = seed.audit;
let trash: Any[] = seed.trash;
const plugins: Any[] = seed.plugins;
let proxyCaptures: Any[] = seed.proxyCaptures;
let proxyRunning = false;
const mockServers: Any[] = seed.mockServers;

const STORE_KEY = "apiark-capture-state-v1";
try {
  const saved = JSON.parse(localStorage.getItem(STORE_KEY) || "null");
  if (saved) {
    if (saved.settings) settings = { ...settings, ...saved.settings };
    if (saved.persisted) persisted = saved.persisted;
  }
} catch { /* ignore */ }
const save = () => {
  try { localStorage.setItem(STORE_KEY, JSON.stringify({ settings, persisted })); } catch { /* ignore */ }
};

const collectionOf = (p: string) =>
  collections.find((c) => p === c.path || p.startsWith(c.path + "/"));
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const jitter = (a: number, b: number) => Math.round(a + Math.random() * (b - a));
const sortNodes = (n: Any[]) => n;

function findNode(nodes: Any[], path: string): Any {
  for (const n of nodes) {
    if (n.path === path) return n;
    if (n.children) { const f = findNode(n.children, path); if (f) return f; }
  }
  return null;
}
function findParent(nodes: Any[], path: string, parent: Any = null): Any {
  for (const n of nodes) {
    if (n.path === path) return parent;
    if (n.children) { const f = findParent(n.children, path, n); if (f) return f; }
  }
  return null;
}

function substitute(s: string, vars: Record<string, string>) {
  return s.replace(/\{\{\s*([\w$.-]+)\s*\}\}/g, (m, k) => {
    if (k === "$uuid") return crypto.randomUUID();
    if (k === "$timestamp") return String(Math.floor(Date.now() / 1000));
    return vars[k] ?? m;
  });
}

function bodyAndHeaders(spec: Any) {
  const body = typeof spec.body === "string" ? spec.body : JSON.stringify(spec.body, null, 2);
  return { body, headers: spec.headers || { "content-type": "application/json" } };
}

const statusText: Record<number, string> = { 200: "OK", 201: "Created", 202: "Accepted", 204: "No Content", 400: "Bad Request", 401: "Unauthorized", 402: "Payment Required", 403: "Forbidden", 404: "Not Found", 409: "Conflict", 422: "Unprocessable Entity", 429: "Too Many Requests", 500: "Internal Server Error", 502: "Bad Gateway" };

function respond(params: Any, variables: Record<string, string> | null, collectionPath: string | null, requestName: string | null) {
  const vars = variables || {};
  const url = substitute(params.url || "", vars);
  let spec: Any = null;
  const c = collectionPath ? collectionOf(collectionPath) : null;
  if (c && requestName) {
    const p = Object.keys(c.files).find((k) => c.files[k].name === requestName);
    if (p) spec = responses[p];
  }
  if (!spec) {
    // match by method + url template across all collections
    for (const col of collections) {
      for (const [p, f] of Object.entries<Any>(col.files)) {
        if (f.method === params.method && responses[p]) {
          const tpl = f.url.replace(/\{\{[^}]+\}\}/g, "").replace(/\?.*$/, "");
          if (tpl && url.split("?")[0].endsWith(tpl.replace(/:\w+/g, "").replace(/\/$/, "")) ) { spec = responses[p]; break; }
        }
      }
      if (spec) break;
    }
  }
  let u: URL | null = null;
  try { u = new URL(url); } catch { /* relative */ }
  if (!spec) {
    // httpbin-style echo for ad-hoc requests
    const hdrs: Record<string, string> = {};
    for (const h of params.headers || []) if (h.enabled && h.key) hdrs[h.key] = substitute(h.value, vars);
    spec = { status: 200, headers: { "content-type": "application/json" }, body: {
      args: u ? Object.fromEntries(u.searchParams) : {}, headers: { Host: u?.host ?? "", "User-Agent": "ApiArk/0.4.6", Accept: "*/*", ...hdrs },
      origin: "73.118.20.4", url, method: params.method, json: (() => { try { return JSON.parse(params.body?.content || "null"); } catch { return null; } })() } };
  }
  const { body, headers } = bodyAndHeaders(spec);
  const now = new Date();
  const hdrs = {
    date: now.toUTCString(), server: u?.host.includes("github") ? "github.com" : "envoy", ...headers,
    "content-length": String(new TextEncoder().encode(body).length), "x-request-id": `req_${Math.random().toString(36).slice(2, 12)}`,
  };
  const status = spec.status;
  const cookies = u && u.host.includes("ledgerly")
    ? [{ name: "ldg_session", value: "s%3Aq8XzP0f1m2.Kd9", domain: u.host, path: "/", httpOnly: true, secure: true }] : [];
  const res = {
    status, statusText: statusText[status] ?? "OK",
    headers: Object.entries(hdrs).map(([key, value], i) => ({ id: `h${i}`, key, value: String(value), enabled: true })),
    cookies, body, timeMs: jitter(48, 320), sizeBytes: new TextEncoder().encode(body).length,
  };
  history.unshift({ id: (history[0]?.id ?? 0) + 1, method: params.method, url, status, statusText: res.statusText, timeMs: res.timeMs, sizeBytes: res.sizeBytes,
    timestamp: now.toISOString(), collectionPath: collectionPath ?? undefined, requestName: requestName ?? undefined, requestJson: JSON.stringify(params) });
  return res;
}

function runTests(testScript: string | null, assertionsYaml: string | null, res: Any) {
  const testResults: Any[] = [];
  if (testScript) {
    const re = /ark\.test\(\s*["'`](.+?)["'`]/g;
    let m;
    while ((m = re.exec(testScript))) testResults.push({ name: m[1], passed: res.status < 400 || /negative|exceeds|declined/i.test(m[1]) });
  }
  const assertionResults: Any[] = [];
  if (assertionsYaml) {
    let parsed: Any = null;
    try { parsed = JSON.parse(res.body); } catch { /* not json */ }
    let current: string | null = null;
    for (const line of assertionsYaml.split("\n")) {
      const top = line.match(/^([\w.$\[\]]+):\s*(.*)$/);
      const nested = line.match(/^\s+(\w+):\s*(.*)$/);
      const get = (path: string) => path === "status" ? res.status : path === "responseTime" ? res.timeMs
        : path.replace(/^body\.?/, "").split(".").filter(Boolean).reduce((o: Any, k) => (o == null ? undefined : o[k]), parsed);
      if (top && top[2]) {
        const expected = JSON.parse(top[2]);
        const actual = get(top[1]);
        assertionResults.push({ path: top[1], operator: "eq", expected, actual, passed: actual === expected });
        current = null;
      } else if (top) current = top[1];
      else if (nested && current) {
        const op = nested[1]; const expected = JSON.parse(nested[2]); const actual = get(current);
        const passed = op === "eq" ? actual === expected : op === "lt" ? actual < expected : op === "gt" ? actual > expected : op === "type" ? (expected === "array" ? Array.isArray(actual) : typeof actual === expected) : true;
        assertionResults.push({ path: current, operator: op, expected, actual, passed });
      }
    }
  }
  return { testResults, assertionResults };
}

function ymd(d: Date) { return d.toISOString(); }

const AI_REPLIES: [RegExp, Any][] = [
  [/test/i, { message: "Here are tests for this request. They check the status code, the shape of the payment intent, and that the amount and currency match what you sent:\n\n```js\nark.test(\"status is 201\", () => ark.expect(ark.response.status).to.equal(201));\nark.test(\"has id\", () => ark.expect(ark.response.json().id).to.match(/^pi_/));\nark.test(\"currency is usd\", () => ark.expect(ark.response.json().currency).to.equal(\"usd\"));\n```\n\nIf you want them to run in CI, add them to the **Tests** tab and run the folder with the Collection Runner.", generatedRequest: null }],
  [/.*/, { message: "Sure — this creates a refund for part of the payment intent. Ledgerly expects `amount` in the smallest currency unit (cents), so $42.50 becomes `4250`. I've also added an `Idempotency-Key` so it's safe to retry.", generatedRequest: { name: "Create partial refund", method: "POST", url: "{{baseUrl}}/v1/refunds", headers: { "Content-Type": "application/json", "Idempotency-Key": "{{$uuid}}" }, body: "{\n  \"payment_intent\": \"{{paymentIntentId}}\",\n  \"amount\": 4250,\n  \"reason\": \"requested_by_customer\"\n}", bodyType: "json", description: "Refund $42.50 of the captured payment" } }],
];

async function handle(cmd: string, a: Any): Promise<Any> {
  switch (cmd) {
    // ── core plugins ──
    case "plugin:app|version": return "0.4.6";
    case "plugin:app|name": return "ApiArk";
    case "plugin:app|tauri_version": return "2.10.1";
    case "plugin:path|resolve_directory": return HOME;
    case "plugin:path|join": return (a.paths as string[]).join("/").replace(/\/+/g, "/");
    case "plugin:path|dirname": return String(a.path).split("/").slice(0, -1).join("/");
    case "plugin:path|basename": return String(a.path).split("/").pop();
    case "plugin:updater|check": return null;
    case "plugin:dialog|open": return null;
    case "plugin:dialog|save": return null;
    case "plugin:dialog|message": case "plugin:dialog|ask": case "plugin:dialog|confirm": return true;
    case "plugin:fs|write_text_file": case "plugin:fs|copy_file": case "plugin:fs|write_file": return null;
    case "plugin:notification|is_permission_granted": return true;
    case "plugin:window|is_maximized": return false;
    case "plugin:window|scale_factor": return 2;
    case "plugin:window|inner_size": case "plugin:window|outer_size": return { width: 2880, height: 1800 };
    case "plugin:window|inner_position": case "plugin:window|outer_position": return { x: 0, y: 0 };

    // ── settings / state ──
    case "get_settings": return settings;
    case "update_settings": settings = { ...settings, ...a.patch }; save(); return settings;
    case "load_persisted_state": return persisted;
    case "save_persisted_state": persisted = a.state; save(); return null;
    case "get_license_status": return { tier: "free", email: null, expiresAt: null, seats: null, gracePeriod: false, valid: true };
    case "get_install_type": return "dmg";
    case "list_rollback_versions": return ["0.4.5", "0.4.4"];

    // ── collections ──
    case "check_collection_version": return { collectionVersion: 1, currentVersion: 1, needsMigration: false, isNewer: false };
    case "open_collection": {
      const c = collectionOf(a.path);
      if (!c) throw `Not an ApiArk collection: ${a.path}`;
      return sortNodes(c.tree);
    }
    case "read_request_file": {
      const f = files[a.path];
      if (!f) throw `File not found: ${a.path}`;
      return structuredClone(f);
    }
    case "save_request_file": files[a.path] = a.request; {
      const c = collectionOf(a.path); const n = c && findNode([c.tree], a.path);
      if (n) { n.name = a.request.name; n.method = a.request.method; }
    } return null;
    case "create_request": {
      const p = `${a.dir}/${a.filename}`.replace(/(\.yaml)?$/, ".yaml");
      files[p] = { name: a.name, method: a.method, url: a.url, headers: {} };
      const c = collectionOf(a.dir); const parent = c && findNode([c.tree], a.dir);
      parent?.children.push({ type: "request", name: a.name, method: a.method, path: p });
      return p;
    }
    case "create_folder": {
      const p = `${a.parent}/${String(a.name).toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;
      const c = collectionOf(a.parent); const parent = c && findNode([c.tree], a.parent);
      parent?.children.push({ type: "folder", name: a.name, path: p, children: [] });
      return p;
    }
    case "rename_item": {
      const c = collectionOf(a.path); const n = c && findNode([c.tree], a.path);
      if (n) n.name = a.newName; if (files[a.path]) files[a.path].name = a.newName;
      return a.path;
    }
    case "delete_item": {
      const c = collectionOf(a.path); const parent = c && findParent([c.tree], a.path);
      if (parent) {
        const node = parent.children.find((x: Any) => x.path === a.path);
        parent.children = parent.children.filter((x: Any) => x.path !== a.path);
        trash.unshift({ name: a.path.split("/").pop(), collectionName: a.collectionName, trashPath: `${HOME}/.apiark/trash/${Date.now()}-${a.path.split("/").pop()}`, deletedAt: new Date().toISOString(), isFolder: node?.type === "folder" });
      }
      return a.path;
    }
    case "save_folder_order": return null;
    case "watch_collection": case "unwatch_collection": return null;
    case "get_collection_defaults": return collectionOf(a.collectionPath)?.defaults ?? { sendCookies: true, storeCookies: true, persistCookies: false };
    case "update_collection_defaults": { const c = collectionOf(a.collectionPath); if (c) c.defaults = a.defaults; return null; }
    case "migrate_collection": return 0;
    case "create_sample_collection": return collections.find((c) => c.name === "Getting Started")?.path;
    case "create_collection": {
      const path = `${a.parentDir}/${String(a.name).toLowerCase().replace(/[^a-z0-9_-]+/g, "-")}`;
      collections.push({ path, name: a.name, tree: { type: "collection", name: a.name, path, children: [] }, files: {}, responses: {}, requests: [], environments: [{ name: "Default", scope: "shared", secrets: [], variables: { baseUrl: "http://localhost:3000" } }], dotenv: {}, cookies: [], git: null, defaults: { sendCookies: true, storeCookies: true, persistCookies: false } });
      return path;
    }

    // ── environments ──
    case "load_environments": return structuredClone(collectionOf(a.collectionPath)?.environments ?? []);
    case "get_resolved_variables": {
      const c = collectionOf(a.collectionPath);
      const env = c?.environments.find((e: Any) => e.name === a.environmentName);
      return { ...(c?.dotenv ?? {}), ...(env?.variables ?? {}) };
    }
    case "load_root_dotenv": return collectionOf(a.collectionPath)?.dotenv ?? {};
    case "save_environment": {
      const c = collectionOf(a.collectionPath); if (!c) return null;
      const i = c.environments.findIndex((e: Any) => e.name === a.env.name);
      const env = { ...a.env, scope: a.scope ?? a.env.scope ?? "shared" };
      if (i >= 0) c.environments[i] = env; else c.environments.push(env);
      return null;
    }

    // ── HTTP ──
    case "send_request": await sleep(jitter(120, 420)); return respond(a.params, a.variables, a.collectionPath, a.requestName);
    case "send_request_with_scripts": {
      await sleep(jitter(140, 460));
      const res = respond(a.params, a.variables, a.collectionPath, a.requestName);
      const { testResults, assertionResults } = runTests(a.testScript, a.assertionsYaml, res);
      const consoleOutput: Any[] = [];
      if (a.preRequestScript) consoleOutput.push({ level: "info", message: "[pre-request] script executed (3 ms)" });
      if (a.postResponseScript) {
        const m = String(a.postResponseScript).match(/console\.log\((.*)\)/);
        consoleOutput.push({ level: "log", message: m ? "token expires in 3600s" : "[post-response] script executed (2 ms)" });
      }
      const envMutations: Record<string, string> = {};
      const sets = String(a.postResponseScript || "").matchAll(/ark\.env\.set\("(\w+)"/g);
      try { const b = JSON.parse(res.body); for (const s of sets) envMutations[s[1]] = b.id ?? b.access_token ?? ""; } catch { /* ignore */ }
      return { ...res, testResults, assertionResults, consoleOutput, envMutations };
    }
    case "read_full_response": return "";

    // ── history ──
    case "get_history": return history.slice(0, 500);
    case "search_history": { const q = String(a.query).toLowerCase(); return history.filter((h) => h.url.toLowerCase().includes(q) || (h.requestName ?? "").toLowerCase().includes(q)); }
    case "clear_history": history = []; return null;

    // ── curl ──
    case "parse_curl_command": {
      const s = String(a.input);
      const url = (s.match(/https?:\/\/[^\s'"]+/) || [""])[0];
      const method = (s.match(/-X\s+(\w+)/) || [])[1] || (/(-d|--data)/.test(s) ? "POST" : "GET");
      const headers: Record<string, string> = {};
      for (const m of s.matchAll(/-H\s+['"]([^:]+):\s*([^'"]*)['"]/g)) headers[m[1]] = m[2];
      const body = (s.match(/(?:-d|--data(?:-raw)?)\s+'([^']*)'/) || [])[1] ?? null;
      return { method, url, headers, body, bodyType: body ? "json" : null, authBasic: null, verifySsl: true, followRedirects: true };
    }
    case "export_curl_command": {
      const h = Object.entries<string>(a.headers || {}).map(([k, v]) => ` \\\n  -H '${k}: ${v}'`).join("");
      return `curl -X ${a.method} '${a.url}'${h}${a.body ? ` \\\n  --data-raw '${a.body}'` : ""}`;
    }

    // ── runner ──
    case "run_collection_command": {
      const c = collectionOf(a.config.collectionPath);
      const reqs = (c?.requests ?? []).filter((r: Any) => (!r.protocol || r.protocol === "http") && (!a.config.folderPath || r.path.startsWith(a.config.folderPath + "/")));
      const iterations: Any[] = [];
      let total = 0, passed = 0, timeTotal = 0;
      for (let it = 1; it <= (a.config.iterations || 1); it++) {
        const results: Any[] = [];
        for (let i = 0; i < reqs.length; i++) {
          const r = reqs[i]; const f = files[r.path];
          await sleep(Math.max(60, a.config.delayMs || 0));
          const status = r.response?.status ?? 200;
          const tests = (f.tests?.match(/ark\.test/g) || []).length;
          const asserts = f.assert ? Object.keys(f.assert).length : 0;
          const flaky = r.name === "Capture payment intent" && it === 1;
          const res = { name: r.name, method: r.method, url: substitute(r.url, {}), status: flaky ? 502 : status, timeMs: jitter(40, 520), passed: !flaky && (status < 400 || asserts > 0), testCount: tests, testPassed: flaky ? 0 : tests, assertionCount: asserts, assertionPassed: flaky ? 0 : asserts, error: flaky ? "Bad Gateway from upstream acquirer" : undefined };
          results.push(res); total++; if (res.passed) passed++; timeTotal += res.timeMs;
          await emit("runner:progress", { runId: "run", iteration: it, requestIndex: i, totalRequests: reqs.length, result: res });
        }
        iterations.push({ iteration: it, results });
      }
      return { totalRequests: total, totalPassed: passed, totalFailed: total - passed, totalTimeMs: timeTotal, iterations };
    }

    // ── websocket / sse (simulated streams) ──
    case "ws_connect": {
      setTimeout(() => emit("ws:status", { connectionId: a.connectionId, state: "connected" }), 250);
      let n = 0;
      const tick = setInterval(() => {
        if (n++ > 12) return clearInterval(tick);
        const content = JSON.stringify({ type: "position", vehicle_id: n % 2 ? "VH-20931" : "VH-20944", lat: 47.6 + Math.random() / 50, lon: -122.33 + Math.random() / 50, speed_kph: jitter(0, 55), ts: new Date().toISOString() });
        emit("ws:message", { connectionId: a.connectionId, direction: "received", content, messageType: "text", timestamp: new Date().toISOString(), sizeBytes: content.length });
      }, 1200);
      return null;
    }
    case "ws_send": emit("ws:message", { connectionId: a.connectionId, direction: "sent", content: a.message, messageType: "text", timestamp: new Date().toISOString(), sizeBytes: a.message.length }); return null;
    case "ws_disconnect": emit("ws:status", { connectionId: a.connectionId, state: "disconnected" }); return null;
    case "sse_connect": {
      setTimeout(() => emit("sse:status", { connectionId: a.connectionId, state: "connected" }), 200);
      const evts = ["trip.assigned", "trip.started", "stop.arrived", "stop.completed", "vehicle.low_battery"];
      let n = 0;
      const tick = setInterval(() => {
        if (n++ > 10) return clearInterval(tick);
        emit("sse:event", { connectionId: a.connectionId, eventType: evts[n % evts.length], data: JSON.stringify({ trip_id: `TR-881${20 + n}`, vehicle_id: "VH-20931", at: new Date().toISOString() }), id: String(9100 + n), timestamp: new Date().toISOString() });
      }, 1500);
      return null;
    }
    case "sse_disconnect": emit("sse:status", { connectionId: a.connectionId, state: "disconnected" }); return null;
    case "socketio_build_url": return `${a.url}/socket.io/?EIO=4&transport=websocket${a.namespace && a.namespace !== "/" ? `&ns=${a.namespace}` : ""}`;
    case "mqtt_connect": case "mqtt_subscribe": case "mqtt_publish": case "mqtt_disconnect": return null;

    // ── oauth ──
    case "oauth_get_token_status": return { hasToken: true, isExpired: false, expiresAt: Math.floor(Date.now() / 1000) + 2710, tokenType: "Bearer" };
    case "oauth_start_flow": return "eyJhbGciOiJSUzI1NiJ9.oauth.local";
    case "oauth_clear_token": return null;

    // ── import / export ──
    case "detect_import_format": return "postman";
    case "import_preview": return { collectionName: "Partner Onboarding (Postman)", requestCount: 23, folderCount: 4, environmentCount: 2, warnings: [{ itemName: "Upload KYC document", message: "File body references a local path that will need re-selecting" }] };
    case "import_collection": return a.targetDir;
    case "import_environment": return "Imported";
    case "export_collection": return `${HOME}/Downloads/${collectionOf(a.collectionPath)?.name ?? "collection"}.${a.format}.json`;

    // ── grpc ──
    case "grpc_load_proto": return [{ name: "Telemetry", fullName: "fleetline.telemetry.v1.Telemetry", methods: [
      { name: "GetVehicleState", fullName: "fleetline.telemetry.v1.Telemetry/GetVehicleState", inputType: "GetVehicleStateRequest", outputType: "VehicleState", callType: "unary" },
      { name: "StreamVehicle", fullName: "fleetline.telemetry.v1.Telemetry/StreamVehicle", inputType: "StreamVehicleRequest", outputType: "TelemetryPoint", callType: "serverStreaming" },
      { name: "UploadPoints", fullName: "fleetline.telemetry.v1.Telemetry/UploadPoints", inputType: "TelemetryPoint", outputType: "UploadSummary", callType: "clientStreaming" } ] }];
    case "grpc_call_unary": case "grpc_call_client_stream": case "grpc_call_bidi_stream":
      await sleep(180);
      return { statusCode: 0, statusMessage: "OK", body: JSON.stringify({ vehicleId: "VH-20931", batteryPct: 64, speedKph: 37.5, location: { lat: 47.6097, lon: -122.3331 }, odometerKm: 48211.4 }, null, 2), timeMs: 142, metadata: [{ key: "content-type", value: "application/grpc" }, { key: "grpc-status", value: "0" }] };
    case "grpc_call_server_stream": case "grpc_disconnect": return null;

    // ── docs ──
    case "preview_docs": case "generate_docs": {
      const c = collectionOf(a.collectionPath);
      const rows = Object.values<Any>(c?.files ?? {}).map((f) => `<tr><td><b>${f.method}</b></td><td><code>${f.url}</code></td><td>${f.name}</td><td>${f.description ?? ""}</td></tr>`).join("");
      return `<!doctype html><html><head><meta charset="utf-8"><title>${c?.name} — API Reference</title><style>body{font-family:system-ui;padding:24px;color:#222}table{border-collapse:collapse;width:100%}td{border-bottom:1px solid #eee;padding:6px 8px;font-size:13px}code{color:#6b21a8}</style></head><body><h1>${c?.name}</h1><p>Generated by ApiArk on ${new Date().toDateString()}.</p><table>${rows}</table></body></html>`;
    }

    // ── monitors ──
    case "list_monitors": return monitors;
    case "get_monitor_results": return monitorResults[a.monitorId] ?? [];
    case "create_monitor": { const m = { id: `mon-${Math.random().toString(16).slice(2, 8)}`, name: a.config.name, collectionPath: a.config.collectionPath, cronExpression: a.config.cronExpression, enabled: true, runCount: 0 }; monitors.push(m); return m; }
    case "delete_monitor": monitors = monitors.filter((m) => m.id !== a.monitorId); return null;
    case "toggle_monitor": { const m = monitors.find((x) => x.id === a.monitorId); if (m) m.enabled = !m.enabled; return m; }

    // ── mock servers ──
    case "list_mock_servers": return mockServers;
    case "start_mock_server": {
      const c = collectionOf(a.config.collectionPath);
      const endpoints = Object.entries<Any>(c?.files ?? {}).filter(([p]) => responses[p]).map(([p, f]) => ({ method: f.method, path: f.url.replace(/\{\{baseUrl\}\}/, "").replace(/\{\{(\w+)\}\}/g, ":$1").split("?")[0] || "/", status: responses[p].status, body: bodyAndHeaders(responses[p]).body, contentType: responses[p].headers?.["content-type"] ?? "application/json" }));
      const s = { id: `mock-${Date.now()}`, collectionName: c?.name ?? "Collection", port: a.config.port, endpoints, running: true };
      mockServers.push(s); return s;
    }
    case "stop_mock_server": { const s = mockServers.find((x) => x.id === a.serverId); if (s) s.running = false; mockServers.splice(mockServers.indexOf(s), 1); return null; }

    // ── cookies ──
    case "get_cookie_jar": return collectionOf(a.collectionPath)?.cookies ?? [];
    case "delete_cookie": { const c = collectionOf(a.collectionPath); if (c) c.cookies = c.cookies.filter((k: Any) => !(k.name === a.name && k.domain === a.domain)); return null; }
    case "clear_cookie_jar": { const c = collectionOf(a.collectionPath); if (c) c.cookies = []; return null; }

    // ── backup / trash ──
    case "export_app_state": return { path: a.outputPath, filesIncluded: ["settings.json", "state.json", "history.db"] };
    case "import_app_state": return { filesRestored: ["settings.json", "state.json"], historyEntries: "395" };
    case "list_trash": return trash;
    case "restore_from_trash": trash = trash.filter((t) => t.trashPath !== a.trashPath); return null;
    case "empty_trash": trash = []; return null;

    // ── plugins ──
    case "list_plugins": return plugins;
    case "toggle_plugin": { const p = plugins.find((x) => x.manifest.name === a.name); if (p) p.enabled = !p.enabled; return p?.enabled ?? false; }
    case "uninstall_plugin": { const i = plugins.findIndex((x) => x.manifest.name === a.name); if (i >= 0) plugins.splice(i, 1); return null; }
    case "install_plugin": return plugins[0];

    // ── proxy ──
    case "proxy_status": return { running: proxyRunning, port: 8888, captureCount: proxyCaptures.length };
    case "proxy_start": proxyRunning = true; return { running: true, port: a.port, captureCount: proxyCaptures.length };
    case "proxy_stop": proxyRunning = false; return { running: false, port: 8888, captureCount: proxyCaptures.length };
    case "proxy_get_captures": return proxyCaptures;
    case "proxy_clear_captures": proxyCaptures = []; return null;
    case "proxy_set_passthrough": return null;
    case "proxy_ca_exists": return true;
    case "proxy_generate_ca": case "proxy_get_ca_cert": return `${HOME}/.apiark/proxy/apiark-ca.pem`;

    // ── AI (LLM stub) ──
    case "ai_chat": case "ai_generate_request": {
      await sleep(900);
      const prompt = String(a.params?.prompt ?? "");
      const reply = AI_REPLIES.find(([re]) => re.test(prompt))![1];
      return cmd === "ai_chat" ? reply : (reply.generatedRequest ?? AI_REPLIES[1][1].generatedRequest);
    }
    case "ai_generate_tests":
      await sleep(900);
      return { tests: "ark.test(\"status is 2xx\", () => {\n  ark.expect(ark.response.status).to.be.within(200, 299);\n});\nark.test(\"returns an id\", () => {\n  ark.expect(ark.response.json()).to.have.property(\"id\");\n});\nark.test(\"responds under 800ms\", () => {\n  ark.expect(ark.response.time).to.be.below(800);\n});", assertions: "status: 201\nbody.object:\n  eq: \"payment_intent\"\nresponseTime:\n  lt: 800" };

    // ── git ──
    case "git_status": {
      const g = collectionOf(a.collectionPath)?.git;
      if (!g) return { isRepo: false, branch: "", isClean: true, ahead: 0, behind: 0, changes: [] };
      return { isRepo: true, branch: g.branch, isClean: g.changes.length === 0, ahead: g.ahead, behind: g.behind, changes: g.changes };
    }
    case "git_log": {
      const g = collectionOf(a.collectionPath)?.git;
      return (g?.log ?? []).map(([hash, message, author, daysAgo]: Any) => ({ hash, message, author, date: ymd(new Date(Date.now() - daysAgo * 86400000)) }));
    }
    case "git_diff": return collectionOf(a.collectionPath)?.git?.diff ?? "";
    case "git_stage": { const g = collectionOf(a.collectionPath)?.git; g?.changes.forEach((c: Any) => { if (a.paths.includes(c.path)) c.staged = true; }); return null; }
    case "git_unstage": { const g = collectionOf(a.collectionPath)?.git; g?.changes.forEach((c: Any) => { if (a.paths.includes(c.path)) c.staged = false; }); return null; }
    case "git_commit": {
      const g = collectionOf(a.collectionPath)?.git; if (!g) throw "Not a git repository";
      const hash = Math.random().toString(16).slice(2, 9);
      g.log.unshift([hash, a.message, "Dana Okafor", 0]); g.changes = g.changes.filter((c: Any) => !c.staged); g.ahead++;
      return hash;
    }
    case "git_push": { const g = collectionOf(a.collectionPath)?.git; if (g) g.ahead = 0; return "Pushed to origin/" + (g?.branch ?? "main"); }
    case "git_pull": return "Already up to date.";
    case "git_init": return "Initialized empty Git repository";

    // ── audit ──
    case "audit_get_logs": return audit.slice(a.offset ?? 0, (a.offset ?? 0) + (a.limit ?? 100));
    case "audit_clear": audit = []; return null;
    case "audit_log_action": audit.unshift({ id: (audit[0]?.id ?? 0) + 1, action: a.action, target: a.target, detail: a.detail ?? "", timestamp: new Date().toISOString() }); return null;

    // ── terminal / window ──
    case "terminal_create": case "terminal_write": case "terminal_resize": case "terminal_close": return null;
    case "open_new_window": return "window-2";
  }
  if (cmd.startsWith("plugin:")) return null;
  console.warn("[apiark-capture mock] unhandled command", cmd, a);
  return null;
}

mockWindows("main");
mockIPC((cmd, args) => handle(cmd, args ?? {}), { shouldMockEvents: true });
